/* Koodo Reader PWA service worker.
 * Generated by scripts/build.mjs: PRECACHE_URLS, PRECACHE_REVISION and
 * RUNTIME_CACHE_PREFIX below are substituted at build time.
 *
 * Strategy:
 *  - Precache: app shell (index.html + built static assets + the vendored
 *    public/lib scripts index.html loads). Installed atomically; old caches
 *    deleted on activate.
 *  - Runtime: same-origin GETs under ./lib/ and ./static/ (wasm, cmaps,
 *    fonts, locale chunks, workers) are cache-first with versioned cache
 *    names, so each deploy gets a fresh runtime cache.
 *  - Navigation fallback: serve cached index.html for same-scope
 *    navigations when offline (hash routing means one document serves all).
 *  - Never cache cross-origin (OCR models, cloud sync endpoints).
 */

const VERSION = "__SW_REVISION__";
const PRECACHE = "koodo-precache-" + VERSION;
const RUNTIME = "koodo-runtime-" + VERSION;
const OFFLINE_URL = "./offline.html";
const PWA_SCOPE_PREFIX = "__SW_SCOPE_PREFIX__"; // e.g. "/koodo-reader/"

// Substituted at build time: JSON array of scope-relative URLs.
const PRECACHE_URLS = __PRECACHE_URLS__;

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(PRECACHE);
      // Cache entries one-by-one so a single bad entry doesn't sink the
      // whole install; the shell files must all succeed though.
      await Promise.all(
        PRECACHE_URLS.map(async (url) => {
          try {
            await cache.add(new Request(url, { cache: "reload" }));
          } catch (error) {
            if (url === OFFLINE_URL || url === "./" || url === "index.html") {
              throw error;
            }
            // Non-shell asset (e.g. a lib script): tolerate and let the
            // runtime cache pick it up later.
          }
        })
      );
      await self.skipWaiting();
    })()
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const keep = new Set([PRECACHE, RUNTIME]);
      const names = await caches.keys();
      await Promise.all(
        names.map((name) => {
          if (name.startsWith("koodo-") && !keep.has(name)) {
            return caches.delete(name);
        }
      })
      );
      if (self.registration.navigationPreload) {
        try {
          await self.registration.navigationPreload.disable();
        } catch (error) {
          /* older browsers */
        }
      }
      await self.clients.claim();
    })()
  );
});

const isSameOrigin = (url) => url.origin === self.location.origin;

// Scope-relative path prefix check: URL must live inside the PWA scope
// (Pages serves the app under /koodo-reader/).
const inScope = (url) =>
  isSameOrigin(url) && url.pathname.startsWith(PWA_SCOPE_PREFIX);

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET") return;

  const url = new URL(request.url);
  if (!inScope(url)) return; // cross-origin (OCR models, sync endpoints)

  // App document navigations: network-first with offline fallback.
  if (request.mode === "navigate") {
    event.respondWith(
      (async () => {
        try {
          const response = await fetch(request);
          return response;
        } catch (error) {
          const cache = await caches.open(PRECACHE);
          const cached =
            (await cache.match("index.html")) ||
            (await cache.match("./")) ||
            (await cache.match(OFFLINE_URL));
          return (
            cached ||
            new Response("Offline", {
              status: 503,
              headers: { "Content-Type": "text/plain" },
            })
          );
        }
      })()
    );
    return;
  }

  // Same-scope static assets: cache-first, populate on miss.
  event.respondWith(
    (async () => {
      const cached = await caches.match(request, {
        ignoreSearch: false,
 });
      if (cached) return cached;
      try {
        const response = await fetch(request);
        if (response && (response.ok || response.type === "opaque")) {
          const cache = await caches.open(RUNTIME);
          // Response body can only be consumed once; clone before use.
          cache.put(request, response.clone());
        }
        return response;
      } catch (error) {
        const cache = await caches.open(PRECACHE);
        const shellFallback = await cache.match(request);
        if (shellFallback) return shellFallback;
        throw error;
      }
    })()
  );
});

// "Open book" from the OS file handler: the page posts the file handle to
// the SW, which remembers it so a newly-activated client (or a client
// reload after install) can pick the book up. Handles aren't structured
// cloneable to IndexedDB, but they do live in a SW variable until the SW
// is killed - good enough for the launch window.
self.addEventListener("message", (event) => {
  if (event.data && event.data.type === "SKIP_WAITING") {
    self.skipWaiting();
  }
  if (event.data && event.data.type === "STORE_FILE_HANDLES") {
    self.__pendingFileHandles = event.data.handles || [];
  }
  if (event.data && event.data.type === "CLAIM_PENDING_FILES") {
    event.source?.postMessage({
      type: "PENDING_FILE_HANDLES",
      handles: self.__pendingFileHandles || [],
    });
    self.__pendingFileHandles = [];
  }
});
